@@ -0,0 +1,123 @@
+using static StrataLint.Scribe.DefinitionDsl;
+using static StrataLint.Scribe.FormulaDsl;
+using F = StrataLint.Scribe.FormulaDsl;
+
+namespace StrataLint.Scribe.Blueprint.D5.S3.Factorization.Galois;
+
+internal sealed class AliabadiSubspaceProductRefutationDocument : IScribeDocumentDefinition
+{
+    private const string Prefix = "D5/S3/Factorization/Galois/AliabadiSubspaceProductRefutation.";
+    private static readonly LibraryNoteRef Source =
+        LibraryNoteRef.Create("D5/L/Factorization/aliabadi2025matchabilityii");
+
+    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
+        "The degree-seven field Q[X]/(X^7-2) refutes Aliabadi's subspace-product lower bound: there are no proper nontrivial intermediate fields, but two five-dimensional subspaces have product span of dimension at most seven, below the proposed lower bound nine.",
+        H("A degree-seven counterexample to the subspace-product conjecture"),
+        Blocks(
+            Node("translate", "Multiplicative field translates", TranslateFormula(),
+                "K and L are arbitrary fields equipped with a K-algebra structure on L. M is an actual intermediate field. Its underlying K-subspace is mapped by the K-linear map x mapped to a times x. Thus translate(a,M) consists exactly of the products am for m in M. The scalar a may be zero.", "translate", true),
+            Node("premise", "The full intermediate-field premise", PremiseFormula(),
+                "The predicate quantifies over every a and b in L and every finite-dimensional intermediate field M that properly contains K and is properly contained in L. Bottom represents the embedded base field and top represents L. Intersections are submodule infima; finrank is dimension over K, and finrank(K,M) is the degree [M:K]. The full ambient field is excluded from this premise.", "intersectionPremise", true),
+            Node("claim", "The whole original conjecture", ClaimFormula(),
+                "This is Conjecture 5.1 of arXiv:2309.14664v1-v3, section 5.1, and Conjecture 38 of the journal article, printed page 154. K and L range over fields with a K-algebra structure on L. A and B are arbitrary finite-dimensional K-subspaces of positive dimensions. S and T range over all K-subspaces of L contained in A and B respectively. No equality of dimensions, separability, infinite-extension condition, dimension-sum restriction, or cap by [L:K] is imposed. The notation span(K,ST) denotes the K-linear span of the actual pointwise product set {st : s in S, t in T}, as defined in section 2.2. The subtraction is natural-number subtraction; at zero-dimensional S and T this gives the same inequality as the ordinary integer interpretation.", "claim", true),
+            Node("polynomial", "The defining polynomial", Disp(Eq(F.Id("polynomial"), Seq(new Formula.Power(F.Id("X"), D(7)), Minus, D(2)))),
+                "The polynomial has rational coefficients. Its integer counterpart is monic and Eisenstein at the prime ideal generated by two: all lower coefficients are divisible by two and the constant coefficient is not divisible by four. Gauss's lemma transfers irreducibility to Q[X].", "polynomial"),
+            Node("extension", "The realized quotient field", Disp(Eq(F.Id("Extension"), Call("AdjoinRoot", F.Id("polynomial")))),
+                "AdjoinRoot is the actual quotient Q[X]/(X^7-2). Irreducibility supplies its field structure. Its canonical power basis has dimension seven, hence it is finite-dimensional over Q. The base-field map is the injective algebra map into this nontrivial field.", "Extension"),
+            Node("alpha", "The class of X", Disp(Eq(F.Id("alpha"), Call("root", F.Id("polynomial")))),
+                "Alpha is the quotient class of X. The quotient-root identity gives alpha to the seventh power equal to two. The canonical basis is 1, alpha, alpha squared, through alpha to the sixth.", "alpha"),
+            Node("span", "Nonconstant power spans", PowerSpanFormula(),
+                "For each natural number n, powerSpan(n) is the span of the actual powers alpha through alpha to the n. Fin n indexes exponents i+1. For n at most six these are distinct entries of the quotient's power basis, so their span has dimension n and does not contain the constant basis vector 1. In particular powerSpan(5) is properly contained in powerSpan(6), and powerSpan(6) is proper in Extension.", "powerSpan"),
+            Node("model", "The realized countermodel certificate", CountermodelFormula(),
+                "Take A=B=powerSpan(6) and S=T=powerSpan(5). These have dimensions six and five, S is properly contained in A, A is proper in L, and 1 is absent from both. Prime extension degree seven makes every intermediate field bottom or top, so the full premise holds for every scalar pair. The actual span of products of S and T is a submodule of the seven-dimensional field; its dimension is therefore at most seven. This upper bound is sufficient, and no equality of that span with the field is asserted here.", "countermodel"),
+            Describe.Lean(
+                DescribeId.Create("aliabadi-subspace-product-result"), DeclarationHandle.Create(Prefix + "result"),
+                H("The uncapped universal bound is false"),
+                StatementSource.FromAuthor(Disp(new Formula.Not(F.Id("claim")))),
+                AssessedProvenance.FromRepo(Source),
+                Blocks(Paragraph(Text("Applying the conjectured conclusion to the realized field and the selected subspaces would give a product-span dimension at least 5+5-1=9. The ambient field bounds that same dimension above by seven, a contradiction. The premise excludes the full intermediate field L and has no other intermediate field to test in prime degree. The refutation therefore concerns the whole original conjecture, including its full intermediate-field premise. It also uses strict proper subspaces, so replacing the ordinary containment symbols by strict containment does not remove this counterexample."))),
+                DescribeRole.Theorem,
+                new OpenProblemResolutionClaim(
+                    ProblemSlugRef.Create("aliabadi-2025-matchability-subspace-product"),
+                    ResolutionKind.Refuted))),
+        []));
+
+    private static DocumentBlock Node(string id, string title, Formula formula, string prose,
+        string declaration, bool literature = false) => Describe.Lean(
+            DescribeId.Create("aliabadi-subspace-product-" + id), DeclarationHandle.Create(Prefix + declaration),
+            H(title), StatementSource.FromAuthor(formula),
+            literature ? AssessedProvenance.FromLiterature(Source) : AssessedProvenance.FromRepo(),
+            Blocks(Paragraph(Text(prose))), DescribeRole.Definition);
+
+    private static Formula Call(string name, params Formula[] args) =>
+        new Formula.Apply(Seq(Operatorname, Grp(F.Id(name))), [.. args]);
+    private static Formula Eq(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.Equal, b);
+    private static Formula Le(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.LessThanOrEqual, b);
+    private static Formula Lt(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.LessThan, b);
+    private static Formula And(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.And, b);
+    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.Implies, b);
+    private static Formula All(string name, Formula type, Formula body) =>
+        Seq(Forall, Sp, Open, F.Id(name), Colon, type, Close, Comma, Sp, body);
+    private static Formula Inst(Formula type, Formula body) => Seq(OpenBracket, type, CloseBracket, Comma, Sp, body);
+    private static Formula Dim(Formula k, Formula s) => Call("finrank", k, s);
+    private static Formula SpanProd(Formula k, Formula s, Formula t) => Call("span", k, Seq(s, Sp, t));
+    private static Formula Subspace(Formula k, Formula l) => Call("Submodule", k, l);
+    private static Formula Finite(Formula k, Formula s) => Call("FiniteDimensional", k, s);
+    private static Formula Q() => Seq(Mathbb, Grp(F.Id("Q")));
+    private static Formula PS(byte n) => Call("powerSpan", D(n));
+    private static Formula Lower(Formula k, Formula s, Formula t) =>
+        Le(Seq(Dim(k, s), Plus, Dim(k, t), Minus, D(1)), SpanDim(k, s, t));
+    private static Formula SpanDim(Formula k, Formula s, Formula t) => Dim(k, SpanProd(k, s, t));
+    private static Formula FieldBinders(Formula body) =>
+        All("K", F.Id("Type"), All("L", F.Id("Type"),
+            Inst(Call("Field", F.Id("K")), Inst(Call("Field", F.Id("L")),
+                Inst(Call("Algebra", F.Id("K"), F.Id("L")), body)))));
+
+    private static Formula TranslateFormula() => Disp(FieldBinders(
+        All("a", F.Id("L"), All("M", Call("IntermediateField", F.Id("K"), F.Id("L")),
+            Eq(Call("translate", F.Id("a"), F.Id("M")),
+                Call("map", Call("mulLeft", F.Id("K"), F.Id("a")), F.Id("M")))))));
+
+    private static Formula PremiseFormula()
+    {
+        Formula k = F.Id("K"), l = F.Id("L"), a = F.Id("a"), b = F.Id("b"), m = F.Id("M");
+        Formula x = F.Id("A"), y = F.Id("B");
+        Formula lhs = Seq(Dim(k, Call("inf", Call("translate", a, m), x)), Plus,
+            Dim(k, Call("inf", Call("translate", b, m), y)));
+        Formula quantified = All("a", l, All("b", l, All("M", Call("IntermediateField", k, l),
+            Imp(And(Lt(Call("bot"), m), And(Lt(m, Call("top")), Finite(k, m))),
+                Le(lhs, Seq(Dim(k, m), Plus, D(1)))))));
+        return Disp(FieldBinders(All("A", Subspace(k, l), All("B", Subspace(k, l),
+            new Formula.Logic(Call("intersectionPremise", x, y), FormulaLogicOperator.Iff, quantified)))));
+    }
+
+    private static Formula ClaimFormula()
+    {
+        Formula k = F.Id("K"), l = F.Id("L"), a = F.Id("A"), b = F.Id("B"), s = F.Id("S"), t = F.Id("T");
+        Formula hypotheses = And(Finite(k, a), And(Finite(k, b),
+            And(Lt(D(0), Dim(k, a)), And(Lt(D(0), Dim(k, b)), Call("intersectionPremise", a, b)))));
+        Formula conclusion = All("S", Subspace(k, l), All("T", Subspace(k, l),
+            Imp(And(Le(s, a), Le(t, b)), Lower(k, s, t))));
+        return Disp(new Formula.Logic(F.Id("claim"), FormulaLogicOperator.Iff,
+            FieldBinders(All("A", Subspace(k, l), All("B", Subspace(k, l), Imp(hypotheses, conclusion))))));
+    }
+
+    private static Formula PowerSpanFormula() => Disp(All("n", Seq(Mathbb, Grp(F.Id("N"))),
+        Eq(Call("powerSpan", F.Id("n")), Call("span", Q(),
+            Call("range", Seq(LambdaLower, Sp, Open, F.Id("i"), Colon, Call("Fin", F.Id("n")), Close,
+                Mapsto, Sp, new Formula.Power(F.Id("alpha"), Seq(Call("val", F.Id("i")), Plus, D(1)))))))));
+
+    private static Formula CountermodelFormula()
+    {
+        Formula l = F.Id("Extension"), q = Q();
+        return Disp(new Formula.Logic(F.Id("countermodel"), FormulaLogicOperator.Iff,
+            new Formula.Aligned([
+                Seq(Eq(Dim(q, l), D(7)), Comma, Sp, Eq(new Formula.Power(F.Id("alpha"), D(7)), D(2)), Comma),
+                Seq(Eq(Dim(q, PS(6)), D(6)), Comma, Sp, Eq(Dim(q, PS(5)), D(5)), Comma),
+                Seq(Lt(PS(5), PS(6)), Comma, Sp, Lt(PS(6), Call("top")), Comma),
+                Seq(new Formula.Not(new Formula.Relation(D(1), FormulaRelationOperator.MemberOf, PS(6))), Comma, Sp, new Formula.Not(new Formula.Relation(D(1), FormulaRelationOperator.MemberOf, PS(5))), Comma),
+                Seq(Call("intersectionPremise", PS(6), PS(6)), Comma),
+                Le(SpanDim(q, PS(5), PS(5)), D(7))
+            ])));
+    }
+}
